fn splitlines(a: Vec<String>, keepends: bool) -> Vec<Vec<String>> {
    a.into_iter()
        .map(|s| {
            let lines: Vec<String> = if keepends {
                // Retain line endings by splitting on line endings with Unicode support.
                let mut result = Vec::new();
                let mut start = 0;
                let bytes = s.as_bytes();

                for (i, &b) in bytes.iter().enumerate() {
                    if b == b'\n' {
                        // Include the '\n'
                        let line = &s[start..=i];
                        result.push(line.to_string());
                        start = i + 1;
                    } else if b == b'\r' {
                        // Check for '\r\n'
                        if i + 1 < bytes.len() && bytes[i + 1] == b'\n' {
                            let line = &s[start..=i+1];
                            result.push(line.to_string());
                            start = i + 2;
                        } else {
                            let line = &s[start..=i];
                            result.push(line.to_string());
                            start = i + 1;
                        }
                    }
                }
                // If there's remaining text after last line ending, add that too
                if start < s.len() {
                    result.push(s[start..].to_string());
                }
                if result.is_empty() {
                    // If string is empty, output at least 1 empty string (input non-empty so this happens iff s = "")
                    vec![String::new()]
                } else {
                    result
                }
            } else {
                // Standard split (like str.lines()) strips line endings
                let iter = s.lines().map(|line| line.to_string()).collect::<Vec<_>>();
                if iter.is_empty() {
                    vec![String::new()]
                } else {
                    iter
                }
            };
            lines
        })
        .collect()
}